-- The service-only tables (RLS pgTAP plan, D3 S1 to S5 and V2): no student reads or writes a
-- `service` table, not even its own rows, and no student reads a closed view. This is the real run
-- against the migrated schema; `09_self_test_test.sql` first saw each probe fail under a planted
-- `for all to authenticated` policy on `judgments` (S1 to S5) and a granted `monthly_spend` (V2).
--
-- Every case is generated by a loop over `tests.matrix`; nothing is written per table. "Per
-- `grants`" (D3): a read is 0 rows at the default grants and a privilege refusal (-1) when they
-- are revoked; an insert is an RLS refusal (-2) or -1; an update, a move or a delete touches
-- nothing, `(0,f)`, or is refused, `(-1,f)`, and in both the owner's re-read finds the target rows
-- unchanged (`tests.probe_write`). Every assertion runs as the owner; only a probe runs as A or B.
--
-- A table with an account key (`account_id`, or `address_id` for the two mailbox-keyed tables)
-- has two slots, A's rows and B's, and each account probes its own: S1 all rows and by its own
-- key, S2 its own row into its cleared slot, S3 its own rows set to the sentinel, S4 its own rows
-- moved to the other account, S5 its own rows deleted. The key is spliced as a literal the owner
-- looked up (for a mailbox-keyed table, the account's one `mail_addresses` id), since the client
-- can read neither `tests.accounts` nor `mail_addresses`.
--
-- A global table (no account key: `webhook_events`, `deleted_accounts`, `models`, `rule_evidence`,
-- `eval_cases`, `eval_runs`) has one slot, the fixture row `tests.slot_where` names, and is probed
-- as A only: `insert_sql` and `slot_where` ignore the account there, so B would send the same
-- statements at the same row. The student's probe never filters on the slot's own `where`: for
-- `rule_evidence` that reads `rules` and `judgments`, which a student cannot see, so it would
-- match nothing under any policy (T8 review). The owner resolves the slot's one row to its
-- primary key instead, and the probe filters on that literal, `row(<key columns>)::text = '<key>'`
-- (`tests.pk_where`, which 09 saw find the row under an allow-all policy on `rule_evidence`). S1
-- reads all rows and the row by that key, S2 inserts the row into its cleared slot, and S3 sets
-- it to the sentinel and S5 deletes it, both by that key; the owner's re-read is still the slot.
-- S4 does not apply: there is no account key to move the row onto, and S3 by the literal key
-- already shows that no update reaches the row at all, so neither can one that re-points
-- `rule_evidence`'s `rule_id` or `judgment_id`.
--
-- `plan()` is computed from `tests.matrix`: six cases per keyed slot, five per global slot, one
-- per closed view, and one guard that the loops are not empty.
begin;
\ir _setup.psql
\ir _matrix.psql
\ir _fixtures.psql

-- The account key's value for `p_who` in table `p_rel`, as text, looked up as the owner: the
-- account id, or for a mailbox-keyed table the account's one mailbox. It raises unless exactly
-- one value exists, so a probe never runs with a null key.
create function tests.t04_key(p_rel text, p_who text) returns text language plpgsql as $$
declare v_key text; v_id uuid; v_val text;
begin
  select m.key_col into strict v_key from tests.matrix m
   where m.rel = p_rel and m.kind = 'table' and m.key_col is not null;
  select a.id into strict v_id from tests.accounts a where a.who = p_who;
  if v_key = 'address_id' then
    select d.id::text into strict v_val from public.mail_addresses d where d.account_id = v_id;
  else
    v_val := v_id::text;
  end if;
  return v_val;
end $$;

-- D3's per-type sentinel for table `p_rel`'s `touch_col`, as a `set` assignment: 'rls-probe' for
-- text, -424242 for numbers, a year ago for timestamps, `not touch_col` for booleans. It raises on
-- any other type, so a probe never sets a column to itself.
create function tests.t04_sentinel(p_rel text) returns text language plpgsql as $$
declare v_col text; v_cat text;
begin
  select m.touch_col, t.typcategory::text into v_col, v_cat
    from tests.matrix m
    join pg_attribute a on a.attrelid = m.rel::regclass and a.attname = m.touch_col
                       and not a.attisdropped
    join pg_type t on t.oid = a.atttypid
   where m.rel = p_rel and m.kind = 'table';
  case v_cat
    when 'S' then return format('%I = %L', v_col, 'rls-probe');
    when 'N' then return format('%I = -424242', v_col);
    when 'D' then return format('%I = now() - interval %L', v_col, '1 year');
    when 'B' then return format('%I = not %I', v_col, v_col);
    else
      raise exception 'tests.t04_sentinel: no sentinel for % (type category %)',
        coalesce(p_rel, '<null>'), coalesce(v_cat, '<none>');
  end case;
end $$;

-- The S slots: every `service` table, A and B for a keyed one, A alone for a global one. The loop
-- below and `plan()` both read this one view, so they cannot disagree.
create view tests.t04_slots as
  select m.rel, m.key_col, m.touch_col, m.grants, w.who,
         case w.who when 'A' then 'B' else 'A' end as other
    from tests.matrix m
   cross join (values ('A'), ('B')) w(who)
   where m.kind = 'table' and m.access = 'service' and (m.key_col is not null or w.who = 'A');

-- S1 to S5 slot by slot, then V2 view by view, in a fixed order. Each probe text is built as the
-- owner before its call; an insert's text is built before the driver clears its slot, and each
-- clear empties only the probed table's own slot, never a parent's.
create function tests.t04_cases() returns setof text language plpgsql as $$
declare
  r record; v_read bigint; v_ins bigint; v_write text; v_slot text; v_pred text;
  v_one text; v_many text; v_insert text; v_clear text; v_set text;
begin
  for r in select * from tests.t04_slots s order by s.rel, s.who loop
    v_read := case r.grants when 'default' then 0 else -1 end;
    v_ins := case r.grants when 'default' then -2 else -1 end;
    v_write := case r.grants when 'default' then '(0,f)' else '(-1,f)' end;
    v_slot := tests.slot_where(r.rel, r.who);
    if r.key_col is null then
      v_pred := tests.pk_where(r.rel, v_slot);
      v_one := format('the global %s row', r.rel);
      v_many := v_one;
    else
      v_pred := format('%I = %L', r.key_col, tests.t04_key(r.rel, r.who));
      v_one := format('its own %s row', r.rel);
      v_many := format('its own %s rows', r.rel);
    end if;
    v_set := tests.t04_sentinel(r.rel);

    return next is(tests.probe(r.who, format('select count(*) from %s', r.rel)), v_read,
      format('S1 all rows: %s reads no row of %s (%s grants, %s)',
        r.who, r.rel, r.grants, v_read));
    return next is(
      tests.probe(r.who, format('select count(*) from %s where %s', r.rel, v_pred)), v_read,
      format('S1 by key: %s reads none of %s (%s grants, %s)', r.who, v_many, r.grants, v_read));

    v_insert := tests.insert_sql(r.rel, r.who);
    v_clear := tests.clear_sql(r.rel, r.who);
    return next is(tests.probe(r.who, v_insert, v_clear), v_ins,
      format('S2: %s''s insert of %s, in its cleared slot, is refused (%s grants, %s)',
        r.who, v_one, r.grants, v_ins));

    return next is(
      tests.probe_write(r.who, r.rel,
        format('update %s set %s where %s', r.rel, v_set, v_pred), v_slot)::text, v_write,
      format('S3: %s''s update of %s (%s to the sentinel) changes nothing (%s grants, %s)',
        r.who, v_many, r.touch_col, r.grants, v_write));

    if r.key_col is not null then
      return next is(
        tests.probe_write(r.who, r.rel,
          format('update %s set %I = %L where %s', r.rel, r.key_col,
            tests.t04_key(r.rel, r.other), v_pred), v_slot)::text, v_write,
        format('S4: %s''s move of %s to %s changes nothing (%s grants, %s)',
          r.who, v_many, r.other, r.grants, v_write));
    end if;

    return next is(
      tests.probe_write(r.who, r.rel, format('delete from %s where %s', r.rel, v_pred),
        v_slot)::text, v_write,
      format('S5: %s''s delete of %s changes nothing (%s grants, %s)',
        r.who, v_many, r.grants, v_write));
  end loop;

  for r in
    select m.rel from tests.matrix m where m.access = 'closed_view' order by m.rel
  loop
    return next is(tests.probe('A', format('select count(*) from %s', r.rel)), -1::bigint,
      format('V2: A''s read of the closed view %s is a privilege refusal (-1)', r.rel));
  end loop;
end $$;

-- One guard, then six cases per keyed slot (S1 twice, S2, S3, S4, S5), five per global slot (no
-- S4) and one per closed view (V2).
select plan(1
  + (select coalesce(sum(case when s.key_col is null then 5 else 6 end), 0)::int
       from tests.t04_slots s)
  + (select count(*)::int from tests.matrix m where m.access = 'closed_view'));

-- Counts only: what the loops cover, and so what the plan above was computed from.
select diag(format('service: %s keyed slots, %s global slots; %s closed views',
  (select count(*) from tests.t04_slots s where s.key_col is not null),
  (select count(*) from tests.t04_slots s where s.key_col is null),
  (select count(*) from tests.matrix m where m.access = 'closed_view')));

-- A loop over nothing passes; this case fails if either domain is empty.
select ok((select count(*) from tests.t04_slots) > 0
          and (select count(*) from tests.matrix m where m.access = 'closed_view') > 0,
  'S and V2 guard: the matrix lists service-table slots and closed views to probe');

select * from tests.t04_cases();

select * from finish();
rollback;
